function editDistanceAtMostOne(a,b){
 a=norm(a);b=norm(b);if(a===b)return true;if(Math.abs(a.length-b.length)>1)return false;
 let i=0,j=0,diffs=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++diffs>1)return false;if(a.length>b.length)i++;else if(b.length>a.length)j++;else{i++;j++;}}
 return diffs+(i<a.length||j<b.length?1:0)<=1;
}
