function upcomingYearMoments(limit=3){
 const dates={septiembre:[8,23],octubre:[9,31],noviembre:[10,16],diciembre:[11,15],enero:[0,30],febrero:[1,15],'febrero-andalucia':[1,28],marzo:[2,20],abril:[3,23],junio:[5,20]},today=new Date();
 today.setHours(0,0,0,0);
 const schoolYear=today.getMonth()>=7?today.getFullYear():today.getFullYear()-1;
 const entries=YEAR_MOMENTS.map(moment=>{const [month,day]=dates[moment[0]],year=month>=8?schoolYear:schoolYear+1;return {moment,date:new Date(year,month,day)};});
 let upcoming=entries.filter(item=>item.date>=today);
 if(upcoming.length<limit)upcoming=upcoming.concat(entries.map(item=>({moment:item.moment,date:new Date(item.date.getFullYear()+1,item.date.getMonth(),item.date.getDate())})));
 return upcoming.sort((a,b)=>a.date-b.date).slice(0,limit);
}
